// nenwa: generated by `nenwa install`. `nenwa setup --remove` deletes this file.
// Tells the nenwa daemon about this OpenCode conversation and hands over messages that arrived for it.
import { spawn } from "node:child_process";

const NENWA = __NENWA_EXE__;

// Runs `nenwa hook opencode <event>` and returns the text to put into the conversation, if any.
function hook(event, input) {
  return new Promise((resolve) => {
    let out = "";
    let p;
    try {
      p = spawn(NENWA, ["hook", "opencode", event], { stdio: ["pipe", "pipe", "ignore"], windowsHide: true });
    } catch {
      return resolve("");
    }
    p.stdout.on("data", (d) => (out += d));
    p.on("error", () => resolve(""));
    p.on("close", () => {
      try {
        const text = JSON.parse(out).text;
        resolve(typeof text === "string" ? text : "");
      } catch {
        resolve("");
      }
    });
    p.stdin.on("error", () => {});
    p.stdin.end(JSON.stringify(input));
  });
}

export const Nenwa = async ({ client, directory, serverUrl }) => {
  const children = new Set(); // sub-agent conversations are not addressable
  const input = (id) => ({ session_id: id, cwd: directory, server_url: String(serverUrl) });
  const say = async (id, text) => {
    try {
      await client.session.promptAsync({ path: { id }, body: { parts: [{ type: "text", text }] } });
    } catch {}
  };
  return {
    event: async ({ event }) => {
      const p = event.properties ?? {};
      const info = p.info;
      if (event.type === "session.created" || event.type === "session.updated") {
        if (info?.parentID) children.add(info.id);
        else if (info?.id && event.type === "session.created") await hook("session-start", input(info.id));
      } else if (event.type === "session.deleted") {
        if (info?.id && !children.delete(info.id)) await hook("session-end", input(info.id));
      } else if (event.type === "session.idle") {
        if (p.sessionID && !children.has(p.sessionID)) {
          const text = await hook("stop", input(p.sessionID));
          if (text) await say(p.sessionID, text);
        }
      }
    },
    "chat.message": async ({ sessionID }) => {
      if (sessionID && !children.has(sessionID)) await hook("user-prompt-submit", input(sessionID));
    },
    "tool.execute.after": async ({ sessionID }, output) => {
      if (!sessionID || children.has(sessionID)) return;
      const text = await hook("post-tool-use", input(sessionID));
      if (text && typeof output.output === "string") output.output += "\n\n" + text;
    },
  };
};
